It's not a few, but here's an example of what Script could be appended to an **AnimatedSprite** to replicate a similar behaviour:
```GDScript
signal frame_refreshed

func _set(property: String, value):
	if property == "flip_h":
		if flip_h == value:
			return
		emit_signal("frame_refreshed")


func play(anim := ""):
	var previous_animation = animation
	var previous_frame = frame
	.play(anim)

	if animation != previous_animation:
		if frame == previous_frame:
			emit_signal("frame_refreshed")
```
